def clean(s):
    s = unicodedata.normalize('NFKC', str(s)).strip()
    s = re.sub(r'\[([^\]]+)\]\([^)]*\)', r'\1', s)
    return re.sub(r'\s+', ' ', s.strip('`* ')).strip()

def norm(s, field, rules):
    if s is None: return None
